{"security_risk": "MEDIUM", "summary": "Create CSS for layout, table, tooltip, and bubble styling", "command": "create", "path": "/root/output/css/style.css", "file_text": ":root {
  --bg: #0b1020;
  --panel: #121a33;
  --text: #e9eefc;
  --muted: #aab6e0;
  --border: rgba(255, 255, 255, 0.12);
  --shadow: 0 10px 25px rgba(0, 0, 0, 0.25);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 18px;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  background: radial-gradient(1200px 600px at 20% 10%, #1a2453 0%, var(--bg) 55%, #070a14 100%);
  color: var(--text);
}

.header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.header h1 {
  font-size: 18px;
  margin: 0;
  letter-spacing: 0.2px;
}

.header .hint {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.layout {
  display: flex;
  gap: 14px;
  align-items: stretch;
}

.panel {
  background: linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02));
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: var(--shadow);
}

#bubblePanel {
  flex: 1 1 62%;
  min-width: 560px;
  padding: 12px;
}

#tablePanel {
  flex: 1 1 38%;
  min-width: 420px;
  padding: 12px;
  display: flex;
  flex-direction: column;
}

#bubbleSvg {
  width: 100%;
  height: 640px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.legend text {
  fill: var(--text);
  font-size: 12px;
}

.legend-title {
  fill: var(--muted);
  font-size: 12px;
}

.node circle {
  stroke: rgba(255,255,255,0.35);
  stroke-width: 1px;
}

.node.selected circle {
  stroke: #ffffff;
  stroke-width: 3px;
}

.node text {
  fill: rgba(255,255,255,0.9);
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
  pointer-events: none;
  paint-order: stroke;
  stroke: rgba(0,0,0,0.45);
  stroke-width: 3px;
}

.table-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.table-title h2 {
  margin: 0;
  font-size: 14px;
}

.table-title .count {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

.table-wrap {
  overflow: auto;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.10);
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: rgba(18, 26, 51, 0.95);
  color: var(--muted);
  text-align: left;
  font-weight: 650;
  padding: 10px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

tbody td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  color: rgba(233, 238, 252, 0.92);
}

tbody tr {
  cursor: pointer;
}

tbody tr:hover {
  background: rgba(255, 255, 255, 0.06);
}

tbody tr.selected {
  background: rgba(90, 160, 255, 0.22);
  outline: 1px solid rgba(90, 160, 255, 0.35);
}

.ticker {
  font-weight: 800;
  letter-spacing: 0.3px;
}

.mcap {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.tooltip {
  position: fixed;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity 120ms ease, transform 120ms ease;
  background: rgba(10, 14, 28, 0.95);
  color: var(--text);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 12px;
  box-shadow: var(--shadow);
  padding: 10px 10px 8px 10px;
  width: 260px;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0);
}

.tooltip .t {
  font-size: 12px;
  font-weight: 800;
  margin: 0 0 4px 0;
}

.tooltip .s {
  margin: 0 0 6px 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.25;
}

.tooltip .meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 6px 0 8px 0;
  font-size: 12px;
  color: rgba(233, 238, 252, 0.92);
}

.tooltip .spark {
  width: 100%;
  height: 48px;
  display: block;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

@media (max-width: 1100px) {
  .layout {
    flex-direction: column;
  }
  #bubblePanel, #tablePanel {
    min-width: 0;
  }
  #bubbleSvg {
    height: 560px;
  }
}
"}

{"security_risk": "MEDIUM", "summary": "Create D3 visualization JavaScript for bubble chart and linked table", "command": "create", "path": "/root/output/js/visualization.js", "file_text": "(() => {
  'use strict';

  const appData = window.STOCK_APP_DATA;
  if (!appData || !Array.isArray(appData.stocks)) {
    document.body.innerHTML = '<pre>Missing STOCK_APP_DATA. Check /output/data/data.js</pre>';
    return;
  }

  const priceHistory = appData.priceHistory || {};

  const formatMarketCap = (value) => {
    if (value === null || value === undefined || !Number.isFinite(+value)) return '—';
    const n = +value;
    const abs = Math.abs(n);
    const fmt = (x) => (x >= 100 ? x.toFixed(0) : x >= 10 ? x.toFixed(1) : x.toFixed(2));

    if (abs >= 1e12) return `${fmt(n / 1e12)}T`;
    if (abs >= 1e9) return `${fmt(n / 1e9)}B`;
    if (abs >= 1e6) return `${fmt(n / 1e6)}M`;
    if (abs >= 1e3) return `${fmt(n / 1e3)}K`;
    return `${n.toFixed(0)}`;
  };

  const formatUSD = (value) => {
    if (value === null || value === undefined || !Number.isFinite(+value)) return '—';
    const n = +value;
    return `$${n.toFixed(2)}`;
  };

  const stocks = appData.stocks
    .map((d) => ({
      ticker: (d.ticker || '').trim(),
      sector: (d.sector || '').trim() || 'Unknown',
      fullName: (d.fullName || '').trim(),
      marketCap: d.marketCap === null || d.marketCap === undefined ? null : +d.marketCap,
      isETF: !!d.isETF || (d.sector || '').trim() === 'ETF' || !Number.isFinite(+d.marketCap),
    }))
    .filter((d) => d.ticker);

  const sectorCounts = d3.rollups(stocks, (v) => v.length, (d) => d.sector)
    .sort((a, b) => d3.descending(a[1], b[1]));

  const sectorOrder = sectorCounts.map((d) => d[0]);
  // Keep ETF last if present.
  const etfIdx = sectorOrder.indexOf('ETF');
  if (etfIdx >= 0) sectorOrder.push(sectorOrder.splice(etfIdx, 1)[0]);

  const color = d3.scaleOrdinal()
    .domain(sectorOrder)
    .range(d3.schemeTableau10.slice(0, sectorOrder.length));

  const bubbleSvgEl = document.getElementById('bubbleSvg');
  const tooltipEl = document.getElementById('tooltip');

  const bubbleHeight = 640;

  const getBubbleWidth = () => {
    const rect = bubbleSvgEl.getBoundingClientRect();
    return Math.max(560, Math.floor(rect.width || 0));
  };

  let selectedTicker = null;

  const setSelected = (ticker) => {
    selectedTicker = ticker;
    updateSelection();
  };

  const updateSelection = () => {
    d3.selectAll('g.node').classed('selected', (d) => d.ticker === selectedTicker);
    d3.selectAll('#stockTable tbody tr').classed('selected', (d) => d.ticker === selectedTicker);

    if (selectedTicker) {
      const row = d3.select('#stockTable tbody')
        .selectAll('tr')
        .filter((d) => d.ticker === selectedTicker)
        .node();
      if (row) row.scrollIntoView({ block: 'center' });

      const node = d3.selectAll('g.node').filter((d) => d.ticker === selectedTicker);
      if (!node.empty()) node.raise();
    }
  };

  const hideTooltip = () => {
    tooltipEl.classList.remove('visible');
  };

  const showTooltip = (event, d) => {
    if (d.isETF) return;

    const ph = priceHistory[d.ticker];
    const lastClose = ph ? ph.lastClose : null;
    const lastDate = ph ? ph.lastDate : null;

    tooltipEl.innerHTML = `
      <p class="t">${d.ticker} � ${d.fullName}</p>
      <p class="s">Sector: ${d.sector}</p>
      <div class="meta">
        <div>Market cap: <strong>${formatMarketCap(d.marketCap)}</strong></div>
        <div>Last close: <strong>${formatUSD(lastClose)}</strong></div>
      </div>
      <svg class="spark" viewBox="0 0 240 48" preserveAspectRatio="none"></svg>
      <p class="s" style="margin-top:6px">${lastDate ? `Price history (end: ${lastDate})` : 'Price history not available'}</p>
    `;

    const svg = d3.select(tooltipEl).select('svg.spark');
    svg.selectAll('*').remove();

    if (ph && Array.isArray(ph.series) && ph.series.length >= 2) {
      const series = ph.series;
      const w = 240;
      const h = 48;
      const x = d3.scaleLinear().domain([0, series.length - 1]).range([8, w - 8]);
      const y = d3.scaleLinear()
        .domain(d3.extent(series, (p) => +p.close))
        .nice()
        .range([h - 10, 10]);

      const line = d3.line()
        .x((p, i) => x(i))
        .y((p) => y(+p.close))
        .curve(d3.curveMonotoneX);

      svg.append('path')
        .attr('d', line(series))
        .attr('fill', 'none')
        .attr('stroke', 'rgba(255,255,255,0.9)')
        .attr('stroke-width', 1.5);

      const last = series[series.length - 1];
      svg.append('circle')
        .attr('cx', x(series.length - 1))
        .attr('cy', y(+last.close))
        .attr('r', 2.6)
        .attr('fill', 'rgba(90,160,255,1)');
    } else {
      svg.append('text')
        .attr('x', 120)
        .attr('y', 26)
        .attr('text-anchor', 'middle')
        .attr('fill', 'rgba(255,255,255,0.6)')
        .attr('font-size', 11)
        .text('No history');
    }

    const pad = 14;
    const xPos = Math.min(window.innerWidth - pad - 260, event.clientX + 14);
    const yPos = Math.min(window.innerHeight - pad - 120, event.clientY + 14);

    tooltipEl.style.left = `${Math.max(pad, xPos)}px`;
    tooltipEl.style.top = `${Math.max(pad, yPos)}px`;
    tooltipEl.classList.add('visible');
  };

  const buildTable = () => {
    const tbody = d3.select('#stockTable tbody');

    const rows = stocks
      .slice()
      .sort((a, b) => {
        const aMc = a.marketCap === null ? -Infinity : a.marketCap;
        const bMc = b.marketCap === null ? -Infinity : b.marketCap;
        if (a.isETF !== b.isETF) return a.isETF ? 1 : -1;
        return d3.descending(aMc, bMc) || d3.ascending(a.ticker, b.ticker);
      });

    document.getElementById('rowCount').textContent = `${rows.length} stocks`;

    const tr = tbody.selectAll('tr')
      .data(rows, (d) => d.ticker)
      .join((enter) => {
        const r = enter.append('tr')
          .on('click', (_, d) => setSelected(d.ticker));

        r.append('td').attr('class', 'ticker').text((d) => d.ticker);
        r.append('td').text((d) => d.fullName || '—');
        r.append('td').text((d) => d.sector || '—');
        r.append('td').attr('class', 'mcap').text((d) => formatMarketCap(d.marketCap));
        return r;
      });

    tr.on('mouseenter', (_, d) => {
      d3.selectAll('g.node').classed('hovered', (n) => n.ticker === d.ticker);
    }).on('mouseleave', () => {
      d3.selectAll('g.node').classed('hovered', false);
    });
  };

  const buildBubbleChart = () => {
    const width = getBubbleWidth();
    const height = bubbleHeight;

    const svg = d3.select(bubbleSvgEl)
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('preserveAspectRatio', 'xMidYMid meet');

    svg.selectAll('*').remove();

    const sectors = sectorOrder.slice();
    const center = { x: width / 2, y: height / 2 + 10 };
    const ringR = Math.min(width, height) * 0.18;

    const sectorPos = new Map();
    sectors.forEach((s, i) => {
      const a = (i / sectors.length) * 2 * Math.PI - Math.PI / 2;
      sectorPos.set(s, {
        x: center.x + ringR * Math.cos(a),
        y: center.y + ringR * Math.sin(a),
      });
    });

    const caps = stocks.filter((d) => !d.isETF && Number.isFinite(d.marketCap)).map((d) => d.marketCap);
    const capExtent = d3.extent(caps);

    const rScale = d3.scaleSqrt()
      .domain(capExtent[0] === undefined ? [0, 1] : capExtent)
      .range([12, 52])
      .clamp(true);

    const ETF_RADIUS = 18;

    const nodes = stocks.map((d) => {
      const r = d.isETF ? ETF_RADIUS : rScale(d.marketCap);
      return {
        ...d,
        r,
        x: center.x + (Math.random() - 0.5) * 40,
        y: center.y + (Math.random() - 0.5) * 40,
      };
    });

    const legend = svg.append('g').attr('class', 'legend').attr('transform', 'translate(14,14)');
    legend.append('text').attr('class', 'legend-title').attr('x', 0).attr('y', 0).text('Sector');

    const legRow = legend.selectAll('g')
      .data(sectors)
      .join('g')
      .attr('transform', (_, i) => `translate(0,${14 + i * 18})`);

    legRow.append('rect')
      .attr('x', 0)
      .attr('y', -10)
      .attr('width', 12)
      .attr('height', 12)
      .attr('rx', 3)
      .attr('fill', (s) => color(s));

    legRow.append('text')
      .attr('x', 18)
      .attr('y', 0)
      .text((s) => s);

    const g = svg.append('g');

    const node = g.selectAll('g.node')
      .data(nodes, (d) => d.ticker)
      .join('g')
      .attr('class', 'node')
      .style('cursor', 'pointer')
      .on('click', (_, d) => setSelected(d.ticker));

    node.append('circle')
      .attr('r', (d) => d.r)
      .attr('fill', (d) => color(d.sector))
      .attr('fill-opacity', (d) => (d.isETF ? 0.72 : 0.88))
      .on('mouseenter', function (event, d) { showTooltip(event, d); })
      .on('mousemove', function (event, d) { showTooltip(event, d); })
      .on('mouseleave', hideTooltip);

    node.append('text')
      .text((d) => d.ticker)
      .attr('font-size', (d) => Math.max(10, Math.min(16, d.r * 0.6)));

    const simulation = d3.forceSimulation(nodes)
      .velocityDecay(0.22)
      .force('x', d3.forceX((d) => (sectorPos.get(d.sector) || center).x).strength(0.16))
      .force('y', d3.forceY((d) => (sectorPos.get(d.sector) || center).y).strength(0.16))
      .force('collide', d3.forceCollide((d) => d.r + 1.2).iterations(2))
      .force('charge', d3.forceManyBody().strength(-10))
      .force('center', d3.forceCenter(center.x, center.y));

    simulation.on('tick', () => {
      for (const d of nodes) {
        d.x = Math.max(d.r, Math.min(width - d.r, d.x));
        d.y = Math.max(d.r, Math.min(height - d.r, d.y));
      }

      node.attr('transform', (d) => `translate(${d.x},${d.y})`);
    });

    // A gentle nudge so clusters settle quickly.
    simulation.alpha(0.9).restart();

    // Save for resize handling.
    return { simulation };
  };

  buildTable();

  let bubbleState = buildBubbleChart();

  // Keep the layout usable when resizing.
  window.addEventListener('resize', () => {
    hideTooltip();
    if (bubbleState && bubbleState.simulation) bubbleState.simulation.stop();
    bubbleState = buildBubbleChart();
    updateSelection();
  });

  // Initial selection: none.
  updateSelection();
})();
"}

