{"security_risk":"MEDIUM","summary":"Create CSS for layout, table, tooltip, and bubble styling","command":"create","path":"/root/output/css/style.css","file_text":":root {
  --bg: #0b1020;
  --panel: #121a33;
  --text: #e9eefc;
  --muted: #aab6e0;
  --border: rgba(255, 255, 255, 0.12);
  --shadow: 0 10px 25px rgba(0, 0, 0, 0.25);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 18px;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  background: radial-gradient(1200px 600px at 20% 10%, #1a2453 0%, var(--bg) 55%, #070a14 100%);
  color: var(--text);
}

.header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.header h1 {
  font-size: 18px;
  margin: 0;
  letter-spacing: 0.2px;
}

.header .hint {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.layout {
  display: flex;
  gap: 14px;
  align-items: stretch;
}

.panel {
  background: linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02));
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: var(--shadow);
}

#bubblePanel {
  flex: 1 1 62%;
  min-width: 560px;
  padding: 12px;
}

#tablePanel {
  flex: 1 1 38%;
  min-width: 420px;
  padding: 12px;
  display: flex;
  flex-direction: column;
}

#bubbleSvg {
  width: 100%;
  height: 640px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.legend text {
  fill: var(--text);
  font-size: 12px;
}

.legend-title {
  fill: var(--muted);
  font-size: 12px;
}

.node circle {
  stroke: rgba(255,255,255,0.35);
  stroke-width: 1px;
}

.node.selected circle {
  stroke: #ffffff;
  stroke-width: 3px;
}

.node text {
  fill: rgba(255,255,255,0.9);
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
  pointer-events: none;
  paint-order: stroke;
  stroke: rgba(0,0,0,0.45);
  stroke-width: 3px;
}

.table-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.table-title h2 {
  margin: 0;
  font-size: 14px;
}

.table-title .count {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

.table-wrap {
  overflow: auto;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.10);
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: rgba(18, 26, 51, 0.95);
  color: var(--muted);
  text-align: left;
  font-weight: 650;
  padding: 10px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

tbody td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  color: rgba(233, 238, 252, 0.92);
}

tbody tr {
  cursor: pointer;
}

tbody tr:hover {
  background: rgba(255, 255, 255, 0.06);
}

tbody tr.selected {
  background: rgba(90, 160, 255, 0.22);
  outline: 1px solid rgba(90, 160, 255, 0.35);
}

.ticker {
  font-weight: 800;
  letter-spacing: 0.3px;
}

.mcap {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.tooltip {
  position: fixed;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity 120ms ease, transform 120ms ease;
  background: rgba(10, 14, 28, 0.95);
  color: var(--text);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 12px;
  box-shadow: var(--shadow);
  padding: 10px 10px 8px 10px;
  width: 260px;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0);
}

.tooltip .t {
  font-size: 12px;
  font-weight: 800;
  margin: 0 0 4px 0;
}

.tooltip .s {
  margin: 0 0 6px 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.25;
}

.tooltip .meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 6px 0 8px 0;
  font-size: 12px;
  color: rgba(233, 238, 252, 0.92);
}

.tooltip .spark {
  width: 100%;
  height: 48px;
  display: block;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

@media (max-width: 1100px) {
  .layout {
    flex-direction: column;
  }
  #bubblePanel, #tablePanel {
    min-width: 0;
  }
  #bubbleSvg {
    height: 560px;
  }
}
"}

