  font-size: 12px;
  line-height: 1.25;
}

.tooltip .meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 6px 0 8px 0;
  font-size: 12px;
  color: rgba(233, 238, 252, 0.92);
}

.tooltip .spark {
  width: 100%;
