}

.node text {
  fill: rgba(255,255,255,0.9);
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
  pointer-events: none;
  paint-order: stroke;
  stroke: rgba(0,0,0,0.45);
  stroke-width: 3px;
}

.table-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.table-title h2 {
  margin: 0;
  font-size: 14px;
}

.table-title .count {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

.table-wrap {
  overflow: auto;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.10);
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: rgba(18, 26, 51, 0.95);
  color: var(--muted);
  text-align: left;
  font-weight: 650;
  padding: 10px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

tbody td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  color: rgba(233, 238, 252, 0.92);
}

tbody tr {
  cursor: pointer;
}

tbody tr:hover {
  background: rgba(255, 255, 255, 0.06);
}

tbody tr.selected {
  background: rgba(90, 160, 255, 0.22);
  outline: 1px solid rgba(90, 160, 255, 0.35);
}

.ticker {
  font-weight: 800;
  letter-spacing: 0.3px;
}

.mcap {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.tooltip {
  position: fixed;
  pointer-events: none;
