  border-radius: 12px;
  box-shadow: var(--shadow);
  padding: 10px 10px 8px 10px;
  width: 260px;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0);
}

.tooltip .t {
  font-size: 12px;
  font-weight: 800;
